#!/usr/bin/env node
// Owner tool: writes apps/mobile/src/design/emberTokens.generated.ts from docs/design/ember/tokens.json.
//
//   node scripts/rn/gen-tokens.mjs            # write the file
//   node scripts/rn/gen-tokens.mjs --check    # exit 1 when the file is not what tokens.json gives
//
// tokens.json is generated by Designer from tokens.css, so nothing in the app is copied by hand.
// Groups: color (four modes), font, space, radius, size are required; type (each style with size,
// lineHeight, weight, family) and typeVar (each style with the name of its CSS variable) are
// written when the file holds them.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const source = join(ROOT, 'docs/design/ember/tokens.json');
const target = join(ROOT, 'apps/mobile/src/design/emberTokens.generated.ts');
const json = JSON.parse(readFileSync(source, 'utf8'));

const fail = (message) => {
  console.error(`gen-tokens: ${message}`);
  process.exit(1);
};

for (const group of ['color', 'font', 'space', 'radius', 'size']) {
  if (!json[group] || typeof json[group] !== 'object') fail(`tokens.json has no group "${group}"`);
}
for (const mode of ['light', 'dark', 'highContrastLight', 'highContrastDark']) {
  if (!json.color[mode]) fail(`tokens.json has no color mode "${mode}"`);
}
if (json.type !== undefined) {
  if (typeof json.type !== 'object' || json.type === null) fail('tokens.json has a "type" that is not an object');
  for (const [style, value] of Object.entries(json.type)) {
    for (const field of ['size', 'lineHeight', 'weight', 'family']) {
      if (!(field in value)) fail(`tokens.json: type.${style} has no "${field}"`);
    }
  }
}
if (json.typeVar !== undefined && (typeof json.typeVar !== 'object' || json.typeVar === null)) {
  fail('tokens.json has a "typeVar" that is not an object');
}

const asNumber = (value) => (/^-?\d+(\.\d+)?px$/.test(value) ? Number.parseFloat(value) : value);
const convert = (value) =>
  value && typeof value === 'object' && !Array.isArray(value)
    ? Object.fromEntries(Object.entries(value).map(([key, inner]) => [key, convert(inner)]))
    : asNumber(value);

const body = { color: json.color, font: json.font, space: json.space, radius: json.radius, size: json.size };
if (json.type !== undefined) body.type = json.type;
if (json.typeVar !== undefined) body.typeVar = json.typeVar;

const text = `/* GENERATED by scripts/rn/gen-tokens.mjs from docs/design/ember/tokens.json. Do not edit by hand. */
/* The color modes follow the cascade of tokens.css: light is :root, dark adds .dark,
   highContrastLight adds .hc, highContrastDark adds .dark, .hc and .dark.hc.
   A CSS px is a pt in React Native. */
export const emberTokens = ${JSON.stringify(convert(body), null, 2)} as const;
`;

if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (current !== text) {
    console.error(`gen-tokens: ${relative(ROOT, target)} is not what tokens.json gives; run: node scripts/rn/gen-tokens.mjs`);
    process.exit(1);
  }
  console.log('gen-tokens: OK');
} else {
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, text);
  console.log(`gen-tokens: wrote ${relative(ROOT, target)}${body.type ? ` with ${Object.keys(body.type).length} text styles` : ''}`);
}
